# Generated by 'podctl completion' from the command table.
_podctl() {
    local cur words cword
    if declare -F _init_completion >/dev/null 2>&1; then
        _init_completion || return
    else
        cur="${COMP_WORDS[COMP_CWORD]}"
        words=("${COMP_WORDS[@]}")
        cword=$COMP_CWORD
    fi

    local cmds="status s battery b bat ping mode m conv c spatial ear ear-detection mic loud-reduction loud press tone-on-press tone rename one-bud-anc obanc auto-anc anc-strength chime chime-volume connect disconnect dc pair unpair forget list ls auto-connect auto volume v vol mute profile p codec default default-sink latency watch w meter ble tray popup reboot completion debug install uninstall help version"
    local globals="--json --pretty --verbose -v --help -h --version"

    local i vi=0 verb=""
    for ((i = 1; i < cword; i++)); do
        if [[ ${words[i]} != -* ]]; then verb="${words[i]}"; vi=$i; break; fi
    done

    if [[ -z $verb ]]; then
        COMPREPLY=( $(compgen -W "$cmds $globals" -- "$cur") )
        return
    fi

    local argpos=$(( cword - vi ))
    case "$verb" in
        mode|m)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "off anc transparency adaptive next" -- "$cur") );;
            esac
            ;;
        conv|c)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "on off" -- "$cur") );;
            esac
            ;;
        spatial)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "off fixed head-tracked" -- "$cur") );;
            esac
            ;;
        ear|ear-detection)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "on off" -- "$cur") );;
            esac
            ;;
        mic)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "auto left right" -- "$cur") );;
            esac
            ;;
        loud-reduction|loud)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "on off" -- "$cur") );;
            esac
            ;;
        press)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "left right" -- "$cur") );;
            2) COMPREPLY=( $(compgen -W "mode-cycle siri none" -- "$cur") );;
            esac
            ;;
        tone-on-press|tone)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "on off" -- "$cur") );;
            esac
            ;;
        one-bud-anc|obanc)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "on off" -- "$cur") );;
            esac
            ;;
        pair)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "--yes -y" -- "$cur") );;
            *) COMPREPLY=( $(compgen -W "--yes -y" -- "$cur") );;
            esac
            ;;
        auto-connect|auto)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "on off" -- "$cur") );;
            esac
            ;;
        mute)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "on off" -- "$cur") );;
            esac
            ;;
        profile|p)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "high headset off" -- "$cur") );;
            esac
            ;;
        codec)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "sbc aac aptx aptx_hd ldac" -- "$cur") );;
            esac
            ;;
        meter)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "--plain --json --once --interval --device" -- "$cur") );;
            *) COMPREPLY=( $(compgen -W "--plain --json --once --interval --device" -- "$cur") );;
            esac
            ;;
        ble)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "on off" -- "$cur") );;
            esac
            ;;
        tray)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "start stop status restart" -- "$cur") );;
            esac
            ;;
        completion)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "bash zsh fish" -- "$cur") );;
            esac
            ;;
        debug)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "--no-redact" -- "$cur") );;
            *) COMPREPLY=( $(compgen -W "--no-redact" -- "$cur") );;
            esac
            ;;
        install)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "--yes -y --force --no-daemon --no-completion --no-manpages --no-tray --no-popup --with-tray --with-popup --gnome-extension" -- "$cur") );;
            *) COMPREPLY=( $(compgen -W "--yes -y --force --no-daemon --no-completion --no-manpages --no-tray --no-popup --with-tray --with-popup --gnome-extension" -- "$cur") );;
            esac
            ;;
        uninstall)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "--yes -y --purge" -- "$cur") );;
            *) COMPREPLY=( $(compgen -W "--yes -y --purge" -- "$cur") );;
            esac
            ;;
        help)
            case $argpos in
            1) COMPREPLY=( $(compgen -W "status battery ping mode conv spatial ear mic loud-reduction press tone-on-press rename one-bud-anc auto-anc chime connect disconnect pair unpair list auto-connect volume mute profile codec default latency watch meter ble tray popup reboot completion debug install uninstall help version" -- "$cur") );;
            esac
            ;;
    esac

    if [[ -z ${COMPREPLY[*]} && $cur == -* ]]; then
        COMPREPLY=( $(compgen -W "$globals" -- "$cur") )
    fi
}
complete -F _podctl podctl
